window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-780e15137b8fc073"]={"versions": [{"id": "FIG-780e15137b8fc073", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Adaptive Platform Timing Extensions. Es modelliert die Struktur und Beziehungen von <code>AgeConstraint</code> innerhalb der Pakete für Timing-Constraints, Timing-Beschreibungen und multidimensionale Zeitangaben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die Klasse <code>AgeConstraint</code>, die via Generalisierung von <code>TimingConstraint::TimingConstraint</code> erbt (welches wiederum als <code>Identifiable</code> und <code>Traceable</code> gekennzeichnet ist).</p>\n<p class=\"fig-p\">Beziehungen und Assoziationen:</p>\n<ul class=\"fig-list\"><li>Assoziation <code>+scope</code> mit Kardinalität <code>0..1</code> auf die Zielklasse <code>TimingDescription::TimingDescriptionEvent</code> aus dem Paket <code>TimingDescription</code>.\n</li><li>Komposition <code>+minimum</code> mit Kardinalität <code>0..1</code> auf die Klasse <code>MultidimensionalTime::MultidimensionalTime</code>.\n</li><li>Komposition <code>+maximum</code> mit Kardinalität <code>0..1</code> auf die Klasse <code>MultidimensionalTime::MultidimensionalTime</code>.\n</li></ul>\n<p class=\"fig-p\">Attribute von <code>MultidimensionalTime</code>:</p>\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType</code>\n</li><li><code>+ cseCodeFactor: Integer</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzablaufdarstellung. <code>AgeConstraint</code> definiert zeitliche Schranken (minimales und maximales Alter) bezogen auf ein referenziertes <code>TimingDescriptionEvent</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives AUTOSAR-Metamodell zur Modellierung von Altersbedingungen. <code>AgeConstraint</code> erfordert eine optionale Referenz auf ein Scope-Event (<code>0..1</code>) sowie optionale Schranken für minimales und maximales Alter (<code>0..1</code>). Die Zeiteinheit und Skalierung in <code>MultidimensionalTime</code> erfolgt über <code>cseCode</code> und <code>cseCodeFactor</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-84146c0616684415", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Adaptive Platform Timing Extensions. Es modelliert die Struktur und Beziehungen von <code>AgeConstraint</code> innerhalb der Pakete für Timing-Constraints, Timing-Beschreibungen und multidimensionale Zeitangaben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die Klasse <code>AgeConstraint</code>, die via Generalisierung von <code>TimingConstraint</code> erbt (welches als <code>Identifiable</code> und <code>Traceable</code> gekennzeichnet ist).</p>\n<p class=\"fig-p\">Beziehungen und Assoziationen:</p>\n<ul class=\"fig-list\"><li>Assoziation <code>+scope</code> mit Kardinalität <code>0..1</code> auf die Zielklasse <code>TimingDescriptionEvent</code> (im Kontext <code>TimingDescription</code>).\n</li><li>Komposition <code>+minimum</code> mit Kardinalität <code>0..1</code> auf die Klasse <code>MultidimensionalTime</code>.\n</li><li>Komposition <code>+maximum</code> mit Kardinalität <code>0..1</code> auf die Klasse <code>MultidimensionalTime</code>.\n</li></ul>\n<p class=\"fig-p\">Attribute von <code>MultidimensionalTime</code>:</p>\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType</code>\n</li><li><code>+ cseCodeFactor: Integer</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzablaufdarstellung. <code>AgeConstraint</code> definiert zeitliche Schranken (minimales und maximales Alter) bezogen auf ein referenziertes <code>TimingDescriptionEvent</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives AUTOSAR-Metamodell zur Modellierung von Altersbedingungen. <code>AgeConstraint</code> erfordert eine optionale Referenz auf ein Scope-Event (<code>0..1</code>) sowie optionale Schranken für minimales und maximales Alter (<code>0..1</code>). Die Zeiteinheit und Skalierung in <code>MultidimensionalTime</code> erfolgt über <code>cseCode</code> und <code>cseCodeFactor</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-098540a4e80e0ec0", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Adaptive Platform Timing Extensions. Es modelliert die Struktur und Beziehungen von <code>AgeConstraint</code> innerhalb der Pakete für Timing-Constraints, Timing-Beschreibungen und multidimensionale Zeitangaben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die Klasse <code>AgeConstraint</code>, die via Generalisierung von <code>TimingConstraint</code> erbt (welches als <code>Identifiable</code> und <code>Traceable</code> gekennzeichnet ist).</p>\n<p class=\"fig-p\">Beziehungen und Assoziationen:</p>\n<ul class=\"fig-list\"><li>Assoziation <code>+scope</code> mit Kardinalität <code>0..1</code> auf die Zielklasse <code>TimingDescriptionEvent</code> (im Kontext <code>TimingDescription</code>).\n</li><li>Komposition <code>+minimum</code> mit Kardinalität <code>0..1</code> auf die Klasse <code>MultidimensionalTime</code>.\n</li><li>Komposition <code>+maximum</code> mit Kardinalität <code>0..1</code> auf die Klasse <code>MultidimensionalTime</code>.\n</li></ul>\n<p class=\"fig-p\">Attribute von <code>MultidimensionalTime</code>:</p>\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType [0..1]</code>\n</li><li><code>+ cseCodeFactor: Integer [0..1]</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzablaufdarstellung. <code>AgeConstraint</code> definiert zeitliche Schranken (minimales und maximales Alter) bezogen auf ein referenziertes <code>TimingDescriptionEvent</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives AUTOSAR-Metamodell zur Modellierung von Altersbedingungen. <code>AgeConstraint</code> erfordert eine optionale Referenz auf ein Scope-Event (<code>0..1</code>) sowie optionale Schranken für minimales und maximales Alter (<code>0..1</code>). Die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> der Zeiteinheit in <code>MultidimensionalTime</code> sind optional (<code>[0..1]</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-780e15137b8fc073", "to": "FIG-84146c0616684415", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Entfernung der redundanten Package-Präfixe <code>TimingConstraint::</code>, <code>MultidimensionalTime::</code> und <code>TimingDescription::</code> in den Klassenheadern von <code>TimingConstraint</code>, <code>MultidimensionalTime</code> und <code>TimingDescriptionEvent</code>.\n</li></ul>"}, {"from": "FIG-84146c0616684415", "to": "FIG-098540a4e80e0ec0", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Bei den Attributen <code>cseCode</code> und <code>cseCodeFactor</code> der Klasse <code>MultidimensionalTime</code> wurden die Multiplizitäten explizit als <code>[0..1]</code> definiert.\n</li></ul>"}]};
